logger = logging.getLogger(__name__)

TOOL_NOT_FOUND_ERROR_MESSAGE = "There is no tool named {tool_name}. Tool must be one of {tools}."
NO_INPUT_ERROR_MESSAGE = "No human input recieved to the agent, Please ask a valid question."
SELF_REFLECTION_PROMPT = "\n\nIf you get the answer to the user's question from the tool calls, do not make any additional tool calls but respond to the user with a final answer. If the question is about a report, call template_report_gen tool at last"


class WarehouseGraphState(BaseModel):
    """State schema for the Report-Warehouse-Agent Graph"""

    messages: list[AnyMessage] = Field(default_factory=list)
    original_query: str = Field(default="", description="Original user query")
    agent_scratchpad: list[AnyMessage] = Field(default_factory=list)  # agent thoughts / intermediate steps
    iteration_count: int = Field(default=0, description="Current iteration count")
    final_answer: str = Field(default="", description="Final answer from the agent")
    previous_conversation: str = Field(default="", description="Previous conversation")


class AgentGraph(AsyncMixin):
    """Warehouse Incident Reporting Agent with native tool calling"""

    @typing.override
    async def __ainit__(
        self,
        llm: BaseChatModel,
        tools: list[BaseTool],
        prompt: ChatPromptTemplate | None = None,
        callbacks: list[BaseCallbackHandler] | None = None,
        retry_parsing_errors: bool = True,
        self_reflection: bool = False,
        max_retries: int = 1,
        max_iterations: int = 10,
    ):
        logger.info("Initializing Agent Graph")
        await super().__ainit__()

        self.llm = llm
        self.tools = tools
        self.llm_with_tools = llm.bind_tools(tools)
        self.callbacks = callbacks or []
        self.retry_parsing_errors = retry_parsing_errors
        self.max_tries = (max_retries + 1) if retry_parsing_errors else 1
        self.max_iterations = max_iterations
        self.self_reflection = self_reflection

        logger.info("Setting up agent with %d tools: %s", len(tools), [tool.name for tool in tools])

        # Use the prompt without injecting tool schemas
        self.agent = prompt | self.llm_with_tools

        self.tools_dict = {tool.name: tool for tool in tools}
        self.graph = await self._build_graph()
        logger.info("Successfully initialized Agent with %d tools", len(self.tools_dict))

    def _get_tool(self, tool_name):
        try:
            return self.tools_dict.get(tool_name)
        except Exception as ex:
            logger.exception("Unable to find tool with the name %s\n%s", tool_name, ex, exc_info=True)
            raise ex

    def _extract_reasoning(self, output_message) -> str:
        """
        Extract reasoning from the new LLM format.
        In the new format, the entire content field contains reasoning/thinking.
        """
        if content := output_message.additional_kwargs.get("reasoning_content", ""):
            return content

        content = output_message.content or ""
        if content.strip():
            # Clean up any <think> tags that might be present (just formatting artifacts)
            import re

            clean_content = re.sub(r"</?think>", "", content).strip()
            return clean_content if clean_content else content.strip()

        return ""

    def _parse_tool_calls_from_content(self, output_message) -> list:
        """
        Parse tool calls from content when they're not in the tool_calls field.
        Handles both JSON format and <TOOLCALL> format.
        """
        import json
        import re

        from langchain_core.messages import ToolCall

        content = output_message.content or ""
        tool_calls = []

        # Try to parse JSON format first: {"name": "...", "arguments": {...}}
        json_pattern = r'\{\s*"name"\s*:\s*"([^"]+)"\s*,\s*"arguments"\s*:\s*(\{[^}]*\}|\{.*?\})\s*\}'
        json_matches = re.findall(json_pattern, content, re.DOTALL)

        for match in json_matches:
            try:
                tool_name = match[0]
                arguments_str = match[1]
                # Parse arguments as JSON
                arguments = json.loads(arguments_str)

                tool_call = ToolCall(name=tool_name, args=arguments, id=f"call_{len(tool_calls)}")
                tool_calls.append(tool_call)
                logger.debug("Parsed JSON tool call: %s with args: %s", tool_name, arguments)
            except (json.JSONDecodeError, KeyError) as e:
                logger.warning("Failed to parse JSON tool call: %s", e)
                continue

        # Try to parse <TOOLCALL> format: <TOOLCALL>[{"name": "...", "arguments": {...}}]</TOOLCALL>
        toolcall_pattern = r"<TOOLCALL>\s*\[(.*?)\]\s*</TOOLCALL>"
        toolcall_matches = re.findall(toolcall_pattern, content, re.DOTALL)

        for match in toolcall_matches:
            try:
                # Parse the JSON array inside TOOLCALL tags
                tool_data_list = json.loads(f"[{match}]")

                for tool_data in tool_data_list:
                    if isinstance(tool_data, dict) and "name" in tool_data and "arguments" in tool_data:
                        tool_call = ToolCall(
                            name=tool_data["name"], args=tool_data["arguments"], id=f"call_{len(tool_calls)}"
                        )
                        tool_calls.append(tool_call)
                        logger.debug(
                            "Parsed TOOLCALL tool call: %s with args: %s", tool_data["name"], tool_data["arguments"]
                        )
            except (json.JSONDecodeError, KeyError) as e:
                logger.warning("Failed to parse TOOLCALL format: %s", e)
                continue

        return tool_calls

    async def astream(self, messages: list[AnyMessage]) -> AsyncGenerator[AgentMessageChunk]:
        """Stream the agent's response."""

        # get conversation_id from ContextVar
        thread_id = ContextState.get().conversation_id.get()
        previous_state = self.graph.get_state({"configurable": {"thread_id": thread_id}}).values

        if previous_state:
            # follow up question, add previous messages to the current messages
            logger.info("Follow a previous conversation %s: %s", thread_id, previous_state)
            # put previous history to agent scratchpad
            try:
                previous_query = previous_state["messages"][-1].content
            except Exception as e:
                logger.error("Failed to get previous query: %s", e)
                previous_query = ""
            agent_scratchpad = [HumanMessage(content=previous_query)]
            ai_agent_scratchpad = previous_state.get("agent_scratchpad", [])
            agent_scratchpad += ai_agent_scratchpad
            # summarize the previous messages into a single message
            summary_prompt = """
            Summarize the history of the conversation, keep important facts with details.
            older conversation summary:{older_conversation_summary}\n\n
            latest messages: "
            """
            previous_messages_summary = await self.llm.ainvoke(
                [
                    HumanMessage(
                        content=summary_prompt.format(
                            older_conversation_summary=previous_state.get("previous_conversation", "")
                        )
                        + "\n".join([m.content for m in agent_scratchpad])
                    )
                ],
            )

            input_state = WarehouseGraphState(
                messages=copy.deepcopy(messages),
                previous_conversation=previous_messages_summary.content,
                agent_scratchpad=[],
                final_answer="",
            )
        else:
            input_state = WarehouseGraphState(
                messages=copy.deepcopy(messages),
            )

        try:
            config = {
                "configurable": {
                    "thread_id": thread_id,
                    "stream": True,
                },
                "recursion_limit": self.max_iterations,
            }
            async for chunk in self.graph.astream(input=input_state, config=config, stream_mode="custom"):
                yield chunk

        except Exception as ex:
            logger.exception("Failed to stream agent: %s", ex, exc_info=True)
            error_chunk = AgentMessageChunk(
                type=AgentMessageChunkType.ERROR,
                content=f"Error: {ex}",
            )
            yield error_chunk

    async def agent_node(self, state: WarehouseGraphState) -> WarehouseGraphState:
        """
        Main reasoning node for warehouse incident analysis.

        Returns:
            WarehouseGraphState: The updated state after reasoning, including the new message from the LLM.
        """

        writer = get_stream_writer()
        try:
            logger.debug("Starting the Agent Node")
            working_state: list[AnyMessage] = []
            for attempt in range(1, self.max_tries + 1):
                if len(state.agent_scratchpad) == 0 and len(working_state) == 0:  # the agent is called the first time
                    if len(state.messages) == 0:
                        raise RuntimeError('No input received in state: "messages"')
                    if isinstance(state.messages[0].content, str) and state.messages[0].content.strip() == "":
                        logger.error("No human input passed to the agent.")
                        state.messages += [AIMessage(content=NO_INPUT_ERROR_MESSAGE)]
                        return state

                question = state.messages[0].content
                logger.debug("Querying agent, attempt: %d", attempt)

                output_message = await self.agent.ainvoke(
                    {
                        "question": question,
                        "agent_scratchpad": state.agent_scratchpad,
                        "chat_history": state.previous_conversation,
                        "current_time": datetime.now(UTC).isoformat(),
                    },
                    config=RunnableConfig(callbacks=self.callbacks),
                )

                # Extract reasoning
                thought = self._extract_reasoning(output_message)
                logger.debug("The user's question was: %s", question)
                logger.debug("The agent's thoughts are:\n%s", thought)
                # Stream the agent's thoughts to the UI
                if thought:
                    writer(AgentMessageChunk(type=AgentMessageChunkType.THOUGHT, content=thought))

                # Do the cycle
                try:
                    # check if the agent has the final answer yet
                    logger.info("Successfully parsed agent response after %d attempts", attempt)
                    if "Final Answer:" in output_message.content:
                        final_answer = output_message.content.split("Final Answer:")[-1].strip()
                        writer(
                            AgentMessageChunk(
                                type=AgentMessageChunkType.FINAL,
                                content=final_answer,
                            )
                        )
                        state.final_answer = final_answer
                        logger.debug("Agent's final answer: %s", final_answer)
                    else:
                        # Agent wants to call a tool (reasoning already streamed above)
                        agent_thought = self._extract_reasoning(output_message)

                        # Check for tool calls in the tool_calls field first
                        tool_calls = (
                            output_message.tool_calls
                            if hasattr(output_message, "tool_calls") and output_message.tool_calls
                            else []
                        )

                        # If no tool_calls, try to parse them from content as fallback
                        if not tool_calls:
                            parsed_tool_calls = self._parse_tool_calls_from_content(output_message)
                            if parsed_tool_calls:
                                logger.info(
                                    "Found %d tool calls in content, using fallback parsing", len(parsed_tool_calls)
                                )
                                tool_calls = parsed_tool_calls

                        if tool_calls:
                            state.agent_scratchpad += [AIMessage(content=agent_thought, tool_calls=tool_calls)]
                        else:
                            # No tool calls, but also no final answer - add to scratchpad and continue
                            state.agent_scratchpad += [AIMessage(content=agent_thought)]
                            # No tool calls and no final answer - just continue with agent's response
                            final_answer = output_message.content.strip()
                            state.final_answer = final_answer
                            logger.debug("Agent's response: %s", final_answer)
                    return state
                except Exception as ex:
                    logger.warning(
                        "Error parsing agent output\nAgent Output:\n%s, Error:\n%s  ",
                        output_message.content,
                        ex,
                    )
                    if attempt == self.max_tries:
                        logger.exception(
                            "Failed to parse agent output after %d attempts, consider enabling or "
                            "increasing max_retries",
                            attempt,
                            exc_info=True,
                        )
                        # the final answer goes in the "messages" state channel
                        state.messages += [output_message]
                        return state
                    # retry parsing errors, if configured
                    logger.info("Retrying Warehouse Agent, including output parsing Observation")
                    working_state.append(output_message)
                    working_state.append(HumanMessage(content=str(ex)))
        except Exception as ex:
            logger.exception("Failed to call agent_node: %s", ex, exc_info=True)

    async def tool_node(self, state: WarehouseGraphState) -> WarehouseGraphState:
        """Execute a tool requested by the agent."""

        try:
            writer = get_stream_writer()
            logger.debug("Starting tool execution")
            if len(state.agent_scratchpad) == 0:
                raise RuntimeError('No tool input received in state: "agent_scratchpad"')
            agent_output: AIMessage = state.agent_scratchpad[-1]
            # Use native tool_calls from the AIMessage
            tool_calls = agent_output.tool_calls if hasattr(agent_output, "tool_calls") else []
            requested_tool_names = [tool_call["name"] for tool_call in tool_calls]
            requested_tools = [self._get_tool(tool_name) for tool_name in requested_tool_names]
            if not requested_tools:
                configured_tool_names = list(self.tools_dict.keys())
                logger.warning(
                    "Agent wants to call tool %s. In the Agent's configuration within the config file,"
                    "there is no tool with that name: %s",
                    requested_tool_names,
                    configured_tool_names,
                )
                error_message = HumanMessage(
                    content=TOOL_NOT_FOUND_ERROR_MESSAGE.format(
                        tool_name=requested_tool_names,
                        tools=configured_tool_names,
                    ),
                )
                state.agent_scratchpad += [error_message]
                return state

            # Run the tool. Try to use structured input, if possible.
            async def run_tool(tool, tool_call):
                try:
                    response = await tool.ainvoke(
                        input={k: v for k, v in tool_call["args"].items() if v is not None},
                        config=RunnableConfig(callbacks=self.callbacks),
                    )
                    # Prepare tool response for agent's context
                    tool_response = f"tool: {tool_call['name']} returned:\n\n {response}"

                    # if tool is template_report_gen, format nicely for UI but keep full response for agent
                    if tool_call["name"] == "template_report_gen":
                        tool_response_for_ui = f"Markdown report available at: {response.http_url} \n\n"
                        tool_response_for_ui += f"PDF report available at: {response.pdf_url} \n\n Snapshot: ![Report Snapshot]({response.image_url})"
                        tool_response_for_ui += f" Video: {response.video_url}"
                        # if report is generated successfully, then we will reach the final_answer state channel
                        state.final_answer = tool_response_for_ui
                        tool_msg = AgentMessageChunk(
                            type=AgentMessageChunkType.FINAL,
                            content=tool_response_for_ui,
                        )
                        writer(tool_msg)
                        # Use full response for agent context
                    elif tool_call["name"] == "multi_incident_formatter":
                        # Bypass LLM for multi_incident_formatter and send directly to UI
                        tool_response_for_ui = response.formatted_incidents
                        # Include chart HTML if available (chart_html already contains both charts joined)
                        if hasattr(response, "chart_html") and response.chart_html:
                            tool_response_for_ui += f"\n\n## Incident Charts\n\n{response.chart_html}\n"
                        tool_msg = AgentMessageChunk(
                            type=AgentMessageChunkType.FINAL,
                            content=tool_response_for_ui,
                        )
                        writer(tool_msg)
                        state.final_answer = tool_response_for_ui
                        # Use full response for agent context
                    else:
                        pass

                    if self.self_reflection:
                        tool_response = f"{tool_response}\n\n + {SELF_REFLECTION_PROMPT}"

                    return ToolMessage(
                        name=tool_call["name"],
                        tool_call_id=tool_call["id"],
                        content=tool_response,
                    )
                except Exception as ex:
                    # Add reflection prompt to error response as well
                    error_response = f"Tool call failed: {ex!s}"

                    return ToolMessage(
                        name=tool_call["name"],
                        tool_call_id=tool_call["id"],
                        content=error_response,
                    )

            import asyncio

            tasks = [run_tool(tool, tool_call) for tool, tool_call in zip(requested_tools, tool_calls, strict=False)]
            for task in asyncio.as_completed(tasks):
                tool_response = await task
                state.agent_scratchpad.append(tool_response)

        except Exception as ex:
            logger.exception("Failed to call tool_node: %s", ex)
            state.agent_scratchpad.append(HumanMessage(content=str(ex)))
        return state

    async def _conditional_edge(self, state: WarehouseGraphState):
        try:
            logger.debug("Starting the Conditional Edge")

            if state.final_answer:
                return AgentDecision.END
            if not state.agent_scratchpad:
                return AgentDecision.AGENT
            agent_output = state.agent_scratchpad[-1]
            if isinstance(agent_output, AIMessage):
                if agent_output.tool_calls:
                    logger.info("Agent is calling %d tools", len(agent_output.tool_calls))
                    return AgentDecision.TOOL
                else:
                    logger.info("Agent ask user to give more information")
                    return AgentDecision.END
            else:
                return AgentDecision.AGENT
        except Exception as ex:
            logger.exception("Failed to determine whether agent is calling a tool: %s", ex, exc_info=True)
            logger.warning("Ending graph traversal")
            return AgentDecision.END

    async def _conditional_edge_from_tool(self, state: WarehouseGraphState):
        """Conditional edge from tool node - check if we should end or continue to agent."""
        try:
            if state.final_answer:
                logger.info("Tool node set final_answer, ending graph traversal")
                return AgentDecision.END
            else:
                logger.debug("Tool finished, continuing to agent")
                return AgentDecision.AGENT
        except Exception as ex:
            logger.exception("Failed to determine next step from tool: %s", ex, exc_info=True)
            return AgentDecision.AGENT

    async def _build_graph(self):
        try:
            self.checkpointer = InMemorySaver()
            graph = StateGraph(WarehouseGraphState)
            graph.add_node("agent", self.agent_node)
            graph.add_node("tool", self.tool_node)
            # Make tool -> agent edge conditional to support tools that set final_answer
            conditional_edge_from_tool_outputs = {
                AgentDecision.END: "__end__",
                AgentDecision.AGENT: "agent",
            }
            graph.add_conditional_edges("tool", self._conditional_edge_from_tool, conditional_edge_from_tool_outputs)
            graph.set_entry_point("agent")
            conditional_edge_possible_outputs = {
                AgentDecision.TOOL: "tool",
                AgentDecision.END: "__end__",
                AgentDecision.AGENT: "agent",
            }
            graph.add_conditional_edges("agent", self._conditional_edge, conditional_edge_possible_outputs)
            self.graph = graph.compile(checkpointer=self.checkpointer)
            logger.info("Agent Graph built and compiled successfully")
            return self.graph
        except Exception as ex:
            logger.exception("Failed to build the Agent Graph: %s", ex, exc_info=ex)
            raise ex


class ReportAgentConfig(FunctionBaseConfig, name="report_agent"):
    """Config for the warehouse incident reporting Agent."""

    tool_names: list[FunctionRef] = Field(
        default_factory=list,
        description="The list of tools to provide to the warehouse reporting agent.",
    )
    llm_name: LLMRef = Field(description="The LLM model to use with the warehouse reporting agent.")
    verbose: bool = Field(default=False, description="Set the verbosity of the agent's logging.")
    log_level: str = Field(default="INFO", description="Logging level for the agent (DEBUG, INFO, WARNING, ERROR).")
    max_iterations: int = Field(default=10, description="Maximum number of iterations for the agent.")
    max_history: int = Field(default=15, description="Maximum number of messages to keep in the conversation history.")
    prompt: str = Field(..., description="The prompt to use for the warehouse reporting agent.")
    self_reflection: bool = Field(default=False, description="Whether to use self reflection prompt for the agent.")


@register_function(config_type=ReportAgentConfig, framework_wrappers=[LLMFrameworkEnum.LANGCHAIN])
async def report_agent(config: ReportAgentConfig, builder: Builder):
    """Warehouse incident reporting agent using AgentGraph pattern"""

    # Configure agent logger level
    agent_logger = logging.getLogger("report_agent.report_agent")
    log_level = getattr(logging, config.log_level.upper(), logging.INFO)
    agent_logger.setLevel(log_level)
    # Ensure handler with filename:line formatter
    if not agent_logger.handlers:
        handler = logging.StreamHandler()
        handler.setLevel(log_level)
        handler.setFormatter(
            logging.Formatter(fmt="%(asctime)s - %(name)s - %(levelname)s - %(filename)s:%(lineno)d - %(message)s")
        )
        agent_logger.addHandler(handler)
    system_prompt = config.prompt

    prompt = ChatPromptTemplate(
        [
            ("system", system_prompt + "\n\n" + "current datetime: {current_time}"),
            ("user", USER_PROMPT),
            MessagesPlaceholder(variable_name="agent_scratchpad", optional=True),
        ]
    )
    if config.verbose:
        print(prompt)
    llm = await builder.get_llm(config.llm_name, wrapper_type=LLMFrameworkEnum.LANGCHAIN)
    tools = await builder.get_tools(tool_names=config.tool_names, wrapper_type=LLMFrameworkEnum.LANGCHAIN)
    agent = await AgentGraph(
        llm=llm,
        tools=tools,
        max_iterations=config.max_iterations,
        prompt=prompt,
        self_reflection=config.self_reflection,
    )

    async def _response_fn(input_message: str) -> AsyncGenerator[str]:
        """Streaming report-agent incident report generation using AgentGraph."""

        logger.info("Creating Report-Agent...")

        try:
            # initialize the starting state with the user query
            messages: list[BaseMessage] = trim_messages(
                messages=[input_message],
                max_tokens=config.max_history,
                strategy="last",
                token_counter=len,
                start_on="human",
                include_system=True,
            )
            async for event in agent.astream(messages=messages):
                if event.type in (AgentMessageChunkType.THOUGHT, AgentMessageChunkType.TOOL_CALL):
                    # Split thinking content by newlines and wrap each in <agent-think-step>
                    lines = event.content.split("\n")
                    steps = []
                    step_num = 0
                    for line in lines:
                        if line.strip():  # Only include non-empty lines
                            step_num += 1
                            steps.append(
                                f'<agent-think-step title="Step{step_num}">\n  {line.strip()}\n</agent-think-step>'
                            )

                    # Wrap all steps in <agent-think> with proper formatting
                    if steps:
                        steps_content = "\n".join(steps)
                        yield f"\n\n<agent-think>\n{steps_content}\n</agent-think>\n\n"
                else:
                    yield f"{event.content}\n\n"

        except Exception as ex:
            logger.exception("Agent failed with exception: %s", ex, exc_info=ex)
            yield f"I seem to be having a problem. {ex}"

    async def _single_fn(input_message: str) -> str:
        message = ""
        async for chunk in _response_fn(input_message):
            message += chunk
        return message

    yield FunctionInfo.create(stream_fn=_response_fn, single_fn=_single_fn)
